export const meta = {
  name: 'session3-wave0',
  description: 'Session 3: WPs A, B, C as parallel pipelines (implement, opus review, mutants+ship)',
  phases: [
    { title: 'Implement', detail: 'sonnet, one worktree per WP, regression first, gates, signed commit' },
    { title: 'Review', detail: 'fresh opus reviewer on the diff only' },
    { title: 'Ship', detail: 'apply review, mutants, gates, push, trail' },
  ],
}

const PLAN = '.claude/plans/PLAN-v1-alpha-close-the-gap.md'
const RULES = `Follow .claude/plans/LAUNCH-v1-alpha-sessions.md "Rules" (build budget env vars, gate by exit code unsandboxed with dangerouslyDisableSandbox, never two builds in one worktree, signed commits, no session links, never merge, no stacks). Trail #357. Use CARGO_BUILD_JOBS=2 and CARGO_PROFILE_DEV_DEBUG=0 CARGO_PROFILE_TEST_DEBUG=0.`

const WPS = [
  { id: 'A', branch: 'chore/real-gates', scope: 'WP A (R5 gates + hygiene, finding F08): justfile `! cargo tree | grep` lines that pass when cargo fails (move boundaries to deny.toml where possible), set shell with pipefail, coverage-per-crate must fail on empty data, bench must exit 1 on failure, graph fixture portability ($CARGO, COPYFILE_DISABLE=1), reword AGENTS.md "Never run cargo builds in parallel" to say "in the same checkout". No changeset.', changeset: false },
  { id: 'B', branch: 'fix/http-parser-blank-lines', scope: 'WP B (F06): provider/http.rs parser truncates a body containing a blank line (rsplit_once("\\r\\n\\r\\n")); use a header-first parse. Boundary test first. Changeset needed.', changeset: true },
  { id: 'C', branch: 'fix/typed-json-input', scope: 'WP C (F10 / R3): cli/io.rs JSON input errors are all E281 usage and file paths ignore --cwd; introduce `enum JsonInput { Stdin, Inline, File(PathBuf) }` carried through resolve_file_arg so errors carry their origin; cli/commands/release_pr.rs args only. Boundary test first. Changeset needed.', changeset: true },
]

const IMPL = { type: 'object', properties: { worktree: { type: 'string' }, branch: { type: 'string' }, commit: { type: 'string' }, gatesPassed: { type: 'boolean' }, notes: { type: 'string' } }, required: ['worktree', 'branch', 'gatesPassed'] }
const REV = { type: 'object', properties: { findings: { type: 'array', items: { type: 'object', properties: { file: { type: 'string' }, issue: { type: 'string' }, fix: { type: 'string' } }, required: ['issue'] } } }, required: ['findings'] }
const SHIP = { type: 'object', properties: { pushed: { type: 'boolean' }, branch: { type: 'string' }, signature: { type: 'string' }, trail: { type: 'string' }, mutantsMissed: { type: 'number' }, gatesPassed: { type: 'boolean' }, notes: { type: 'string' } }, required: ['pushed', 'gatesPassed'] }

const results = await pipeline(
  WPS,
  wp => agent(
    `Implement ${wp.scope}\nRead ${PLAN} (root-cause table, settled decisions, the WP row) and AGENTS.md. Re-verify the finding against current main first; if it is already fixed or another branch owns it, say so and stop with gatesPassed=false. In your isolated worktree run \`git switch -c ${wp.branch} origin/main\` (try \`git fetch\` first; if the network is blocked, use local origin/main and note it). Write the regression test first at the real boundary, fix the root cause by the first rung that works, fix structural siblings in the same change, update specs/docs in the same change. ${wp.changeset ? 'Add a changeset with `callisto add --package cargo/callisto-cli:<bump> --summary "..."` per AGENTS.md rules.' : 'No changeset.'} Run \`just pre-push && just lint && just doc-check && just test\` and judge by exit code. Commit signed (never disable gpgsign). Do not push. Return the worktree absolute path, branch, commit sha. ${RULES}`,
    { label: `impl:${wp.id}`, phase: 'Implement', model: 'sonnet', isolation: 'worktree', schema: IMPL }),
  (impl, wp) => {
    if (!impl || !impl.gatesPassed) return { impl, review: null }
    return agent(
      `Fresh-context review of WP ${wp.id}. Finding: ${wp.scope}\nIn ${impl.worktree} (branch ${impl.branch}) read \`git diff origin/main...HEAD\`. You read only; never build or edit. Return only real defects: wrong fix, missed sibling with the same defect, test that cannot fail, over-engineering against AGENTS.md invariants. Empty list if none.`,
      { label: `review:${wp.id}`, phase: 'Review', model: 'opus', schema: REV }).then(review => ({ impl, review }))
  },
  (prev, wp) => {
    if (!prev || !prev.impl || !prev.impl.gatesPassed) return null
    const { impl, review } = prev
    return agent(
      `Ship WP ${wp.id} in ${impl.worktree} (branch ${impl.branch}).\n1. Apply review findings that hold up (verify each against the code; skip the rest and say why): ${JSON.stringify(review ? review.findings : [])}\n2. Run \`cargo mutants --in-place --in-diff <diff of origin/main...HEAD>\` for the Rust diff (skip if the diff has no Rust); zero missed, add tests for survivors, an equivalent mutant gets one line in the PR body.\n3. Re-run \`just pre-push && just lint && just doc-check && just test\` unsandboxed, judge by exit code.\n4. Commit signed, push the branch, create or link the trail with \`entire trail create\` / \`entire trail ci-pr\` (trail #357; run \`entire agent-help\` for exact flags). Do not open the PR with gh. Verify \`gh api repos/orin-dx/callisto/commits/<sha> --jq .commit.verification.reason\` is valid.\n5. After push, \`rm -rf <worktree>/target\`.\nNever merge. ${RULES}`,
      { label: `ship:${wp.id}`, phase: 'Ship', model: 'sonnet', schema: SHIP })
  }
)
return results

