638	/// Rewrites one dependency edge toward `new`. A range a consumer's published manifest would keep excluding `new`
639	/// stops the run; only a dev dependency, which consumers never install, is left alone with a warning.
640	pub(crate) fn rewrite_edge(edge: &DepEdge, new: &Version, cfg: &CascadeConfig) -> Result<RewriteOutcome, GraphError> {
641	    let eco = manifest_ecosystem(&edge.from_manifest);
642	    match rewrite_spec(&edge.spec, new, eco, cfg) {
643	        RewriteOutcome::LeftAlone(_) if edge.kind != DepKind::Dev => Err(GraphError::UnrewritableRange {
644	            dependent: edge.from.display_name(),
645	            dependency: edge.to.display_name(),
646	            spec: edge.spec.render(),
647	            version: new.render().to_string(),
648	            manifest: edge.from_manifest.display().to_string(),
649	        }),
650	        outcome => Ok(outcome),
651	    }
