654	pub fn rewrite_spec(original: &DepSpec, new: &Version, eco: Ecosystem, cfg: &CascadeConfig) -> RewriteOutcome {
655	    if !cfg.preserve_npm_ranges && eco == Ecosystem::Npm && !matches!(original, DepSpec::WorkspaceProtocol(_)) {
656	        return RewriteOutcome::Rewritten(DepSpec::Exact(new.clone()));
657	    }
658	
659	    // A rewrite that still excludes `new` is no rewrite: the dependent would publish a range its dependency cannot meet.
660	    match callisto_manifests::round_trip(eco, original, new)
661	        .filter(|rewritten| matches!(coverage(rewritten, new), Ok(Coverage::Covers | Coverage::Unknown)))
662	    {
663	        Some(rewritten) => RewriteOutcome::Rewritten(rewritten),
664	        _ => RewriteOutcome::LeftAlone(Diagnostic {
665	            code: DiagnosticCode::RangeNotRoundTrippable,
666	            severity: DiagnosticSeverity::Warning,
667	            message: format!(
668	                "spec `{}` could not be round-tripped toward version `{}`",
669	                original.render(),
670	                new.render()
671	            ),
672	            package: None,
673	            path: None,
674	            governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
675	            escalated_by: None,
676	        }),
677	    }
678	}
